// window.RESOURCES : id -> {kind,title,url,src,year,note,essential,group,topics}
// window.LIBRARY_GROUPS : ordered group names
window.LIBRARY_GROUPS = [
  'Start here',
  'Foundations and arithmetic',
  'Attention kernels',
  'KV cache and memory',
  'Scheduling and batching',
  'Quantization and numerics',
  'Speculative and parallel decoding',
  'Distributed and disaggregated serving',
  'Production and serving infrastructure',
  'Benchmarking and profiling',
  'Courses and lectures',
  'Codebases to read',
  'Engine documentation',
  'Economics and the frontier'
];

window.RESOURCES = {};

var G_START = 'Start here',
    G_FOUND = 'Foundations and arithmetic',
    G_KERN = 'Attention kernels',
    G_KV = 'KV cache and memory',
    G_SCHED = 'Scheduling and batching',
    G_QUANT = 'Quantization and numerics',
    G_SPEC = 'Speculative and parallel decoding',
    G_DIST = 'Distributed and disaggregated serving',
    G_PROD = 'Production and serving infrastructure',
    G_BENCH = 'Benchmarking and profiling',
    G_COURSE = 'Courses and lectures',
    G_CODE = 'Codebases to read',
    G_DOCS = 'Engine documentation',
    G_ECON = 'Economics and the frontier';

function R(id, kind, title, url, src, year, note, group, topics, essential) {
  window.RESOURCES[id] = {
    id: id, kind: kind, title: title, url: url, src: src, year: year,
    note: note, group: group, topics: topics || [], essential: !!essential
  };
}

/* ---- Start here ---- */
R('r-ttft-repo', 'course', 'Time to First Token', 'https://github.com/patchy631/time-to-first-token', 'patchy631', 2025, 'A ten-week structured walk through inference optimisation. Useful as a second opinion on ordering: it also puts the roofline before any kernel work.', G_START, ['curriculum', 'overview'], true);
R('r-modular-handbook', 'book', 'Modular AI Handbook: Inference Optimization', 'https://handbook.modular.com/inference-optimization/', 'Modular', 2025, 'The single best free prose treatment of the serving stack. Every chapter is short, correct, and written by people who ship a runtime.', G_START, ['overview', 'serving'], true);
R('r-modular-basics', 'book', 'How Does LLM Inference Work?', 'https://handbook.modular.com/llm-inference-basics/how-does-llm-inference-work/', 'Modular', 2025, 'The prerequisite chapter. Read it if the prefill/decode split is not yet second nature.', G_START, ['overview'], false);
R('r-kipply', 'blog', 'Transformer Inference Arithmetic', 'https://kipp.ly/transformer-inference-arithmetic/', 'kipply', 2022, 'The canonical arithmetic post. Derives FLOPs, memory movement, and the batch size at which decode stops being memory bound.', G_START, ['arithmetic', 'roofline'], true);
R('r-brrr', 'blog', 'Making Deep Learning Go Brrrr From First Principles', 'https://horace.io/brrr_intro.html', 'Horace He', 2022, 'Compute bound, memory bound, overhead bound. Three regimes, three different fixes. Internalise this taxonomy before touching a profiler.', G_START, ['roofline', 'profiling'], true);
R('r-tensor-economics', 'blog', 'LLM Inference Economics from First Principles', 'https://www.tensoreconomics.com/p/llm-inference-economics-from-first', 'Tensor Economics', 2025, 'Builds cost per million tokens from hardware constants upward, and shows why batch size is the dominant lever on unit cost.', G_START, ['economics', 'arithmetic'], true);
R('r-lilian-inference', 'blog', 'Large Transformer Model Inference Optimization', 'https://lilianweng.github.io/posts/2023-01-10-inference-optimization/', 'Lilian Weng', 2023, 'A dense literature map: distillation, quantisation, sparsity, architecture. Good for finding the name of a technique you half remember.', G_START, ['survey'], false);

/* ---- Foundations and arithmetic ---- */
R('r-attention-paper', 'paper', 'Attention Is All You Need', 'https://arxiv.org/abs/1706.03762', 'Vaswani et al., NeurIPS', 2017, 'Read it for the shapes, not the novelty. Every cost model in this track is a function of d_model, n_heads, n_layers and the shapes in section 3.', G_FOUND, ['architecture'], true);
R('r-roofline-paper', 'paper', 'Roofline: An Insightful Visual Performance Model', 'https://dl.acm.org/doi/10.1145/1498765.1498785', 'Williams, Waterman, Patterson, CACM', 2009, 'The original. The ridge point idea is the whole reason decode and prefill need different optimisations.', G_FOUND, ['roofline'], true);
R('r-pope-scaling', 'paper', 'Efficiently Scaling Transformer Inference', 'https://arxiv.org/abs/2211.05102', 'Pope et al., MLSys', 2023, 'The paper that made inference a systems discipline. Partitioning strategies, cost equations, and the first serious latency/throughput Pareto analysis.', G_FOUND, ['arithmetic', 'parallelism'], true);
R('r-llm-numbers', 'code', 'Numbers Every LLM Developer Should Know', 'https://github.com/ray-project/llm-numbers', 'Ray / Anyscale', 2023, 'Order of magnitude anchors. Use it to sanity check any estimate you produce.', G_FOUND, ['arithmetic'], false);
R('r-modal-gpu-glossary', 'docs', 'Modal GPU Glossary', 'https://modal.com/gpu-glossary', 'Modal', 2025, 'SM, warp, CTA, HBM, L2, tensor core, all defined precisely with links into the CUDA docs. Keep it open while reading kernel papers.', G_FOUND, ['hardware'], true);
R('r-h100-whitepaper', 'docs', 'NVIDIA H100 Tensor Core GPU Datasheet', 'https://resources.nvidia.com/en-us-hopper-architecture/nvidia-tensor-core-gpu-datasheet', 'NVIDIA', 2023, 'The authoritative source for the numbers you will use constantly: 989 TFLOP/s BF16 dense, 3.35 TB/s HBM3, 80 GB. Halve anything quoted with sparsity.', G_FOUND, ['hardware'], true);
R('r-nvidia-inference-guide', 'blog', 'Mastering LLM Techniques: Inference Optimization', 'https://developer.nvidia.com/blog/mastering-llm-techniques-inference-optimization/', 'NVIDIA', 2023, 'A vendor overview that is unusually honest about tradeoffs. Good breadth-first index into the technique space.', G_FOUND, ['survey'], false);
R('r-databricks-perf', 'blog', 'LLM Inference Performance Engineering: Best Practices', 'https://www.databricks.com/blog/llm-inference-performance-engineering-best-practices', 'Databricks', 2023, 'Introduces the four-metric vocabulary (TTFT, TPOT, latency, throughput) that the rest of the industry adopted.', G_FOUND, ['metrics'], true);
R('r-survey-inference', 'paper', 'A Survey on Efficient Inference for Large Language Models', 'https://arxiv.org/abs/2404.14294', 'Zhou et al.', 2024, 'The most complete taxonomy available. Use it as an index, not a read-through.', G_FOUND, ['survey'], false);
R('r-pmpp', 'book', 'Programming Massively Parallel Processors (4th ed.)', 'https://www.sciencedirect.com/book/9780323912310/programming-massively-parallel-processors', 'Hwu, Kirk, El Hajj', 2022, 'The standard GPU programming text. Chapters on memory coalescing and tiling are the prerequisite for understanding FlashAttention.', G_FOUND, ['hardware', 'cuda'], false);
R('r-ml-engineering', 'code', 'Machine Learning Engineering Open Book', 'https://github.com/stas00/ml-engineering', 'Stas Bekman', 2025, 'Field notes from someone who has debugged real clusters. The network and hardware chapters are worth the whole repository.', G_FOUND, ['hardware', 'ops'], false);
R('r-tpu-book', 'book', 'How to Scale Your Model', 'https://jax-ml.github.io/scaling-book/', 'Google DeepMind', 2025, 'TPU-flavoured but the reasoning is universal: it derives arithmetic intensity and communication cost for every parallelism scheme from first principles.', G_FOUND, ['parallelism', 'arithmetic'], true);
R('r-ultrascale', 'book', 'The Ultra-Scale Playbook', 'https://huggingface.co/spaces/nanotron/ultrascale-playbook', 'Hugging Face', 2025, 'Training-focused, but the parallelism and collective communication chapters transfer directly to multi-GPU inference.', G_FOUND, ['parallelism'], false);
R('r-littles-law', 'blog', "Little's Law", 'https://en.wikipedia.org/wiki/Little%27s_law', 'Wikipedia', 2024, 'L = lambda W. Three symbols that determine whether your SLO and your throughput target are simultaneously satisfiable.', G_FOUND, ['queueing', 'capacity'], false);
R('r-mqa-paper', 'paper', 'Fast Transformer Decoding: One Write-Head Is All You Need', 'https://arxiv.org/abs/1911.02150', 'Shazeer', 2019, 'MQA. The first paper to treat the KV cache as the binding constraint rather than an implementation detail.', G_FOUND, ['attention', 'kv-cache'], false);
R('r-gqa-paper', 'paper', 'GQA: Training Generalized Multi-Query Transformer Models', 'https://arxiv.org/abs/2305.13245', 'Ainslie et al., EMNLP', 2023, 'The interpolation between MHA and MQA that essentially every modern open model uses. Read it for the uptraining recipe too.', G_FOUND, ['attention', 'kv-cache'], true);
R('r-mistral-swa', 'paper', 'Mistral 7B', 'https://arxiv.org/abs/2310.06825', 'Jiang et al.', 2023, 'Sliding window attention plus a rolling buffer cache. A clean worked example of bounding KV memory by architecture rather than by eviction policy.', G_FOUND, ['attention', 'kv-cache'], false);

/* ---- Attention kernels ---- */
R('r-online-softmax', 'paper', 'Online Normalizer Calculation for Softmax', 'https://arxiv.org/abs/1805.02867', 'Milakov, Gimelshein', 2018, 'The rescaling trick that makes FlashAttention possible. Derive it yourself before reading FlashAttention or the tiling will look like magic.', G_KERN, ['kernels', 'softmax'], true);
R('r-rabe-staats', 'paper', 'Self-attention Does Not Need O(n^2) Memory', 'https://arxiv.org/abs/2112.05682', 'Rabe, Staats', 2021, 'The memory argument, one year before FlashAttention added the IO-aware scheduling that made it fast as well as small.', G_KERN, ['kernels'], false);
R('r-flashattn1', 'paper', 'FlashAttention: Fast and Memory-Efficient Exact Attention with IO-Awareness', 'https://arxiv.org/abs/2205.14135', 'Dao et al., NeurIPS', 2022, 'The paper to read line by line. Section 3 contains the HBM access count analysis that justifies every design decision.', G_KERN, ['kernels', 'attention'], true);
R('r-flashattn2', 'paper', 'FlashAttention-2: Faster Attention with Better Parallelism and Work Partitioning', 'https://arxiv.org/abs/2307.08691', 'Dao, ICLR', 2023, 'Fewer non-matmul FLOPs, better warp-level partitioning, sequence-length parallelism. A masterclass in occupancy reasoning.', G_KERN, ['kernels'], true);
R('r-flashattn3', 'paper', 'FlashAttention-3: Fast and Accurate Attention with Asynchrony and Low-precision', 'https://arxiv.org/abs/2407.08608', 'Shah et al., NeurIPS', 2024, 'Hopper specific: warp specialisation, TMA, and FP8 attention with incoherent processing to control outliers.', G_KERN, ['kernels', 'fp8'], false);
R('r-flashattn3-blog', 'blog', 'FlashAttention-3: Asynchrony and Low-Precision', 'https://tridao.me/blog/2024/flash3/', 'Tri Dao', 2024, 'The author explaining the producer/consumer warp structure in prose. Read before the paper.', G_KERN, ['kernels'], false);
R('r-flashdecoding', 'blog', 'Flash-Decoding for Long-Context Inference', 'https://pytorch.org/blog/flash-decoding/', 'PyTorch', 2023, 'Why the prefill kernel is the wrong kernel for decode, and how splitting along the KV length restores parallelism when batch and heads are small.', G_KERN, ['kernels', 'decode'], true);
R('r-flashinfer', 'paper', 'FlashInfer: Efficient and Customizable Attention Engine for LLM Inference Serving', 'https://arxiv.org/abs/2501.01005', 'Ye et al., MLSys', 2025, 'A block-sparse formulation that unifies paged, ragged, and prefix-shared attention behind one kernel generator. Now the default backend in several engines.', G_KERN, ['kernels', 'serving'], true);
R('r-thunderkittens', 'code', 'ThunderKittens', 'https://github.com/HazyResearch/ThunderKittens', 'HazyResearch', 2024, 'A tile primitive library that makes hand-written Hopper kernels legible. Good for seeing what FA3 does without reading 3000 lines of CUTLASS.', G_KERN, ['kernels', 'cuda'], false);
R('r-flash-linear-attn', 'code', 'flash-linear-attention', 'https://github.com/fla-org/flash-linear-attention', 'FLA Org', 2025, 'Triton implementations of linear attention variants. The reference point if you want to compare subquadratic architectures honestly.', G_KERN, ['kernels', 'architecture'], false);
R('r-ring-attention', 'paper', 'Ring Attention with Blockwise Transformers for Near-Infinite Context', 'https://arxiv.org/abs/2310.01889', 'Liu, Zaharia, Abbeel, ICLR', 2024, 'Sequence parallelism for attention: overlap the KV block rotation with compute and context length stops being bounded by one device.', G_KERN, ['long-context', 'parallelism'], false);
R('r-mamba', 'paper', 'Mamba: Linear-Time Sequence Modeling with Selective State Spaces', 'https://arxiv.org/abs/2312.00752', 'Gu, Dao', 2023, 'The serious challenger to attention at inference time: constant state per token instead of a growing KV cache. Read for the hardware-aware scan.', G_KERN, ['architecture'], false);
R('r-rwkv', 'paper', 'RWKV: Reinventing RNNs for the Transformer Era', 'https://arxiv.org/abs/2305.13048', 'Peng et al.', 2023, 'Another constant-memory decode architecture. Useful contrast: it shows the KV cache is a design choice, not a law.', G_KERN, ['architecture'], false);

/* ---- KV cache and memory ---- */
R('r-vllm-paper', 'paper', 'Efficient Memory Management for LLM Serving with PagedAttention', 'https://arxiv.org/abs/2309.06180', 'Kwon et al., SOSP', 2023, 'The most important systems paper in this field. Virtual memory for the KV cache: fragmentation drops from 60-80% to under 4%.', G_KV, ['kv-cache', 'serving'], true);
R('r-vattention', 'paper', 'vAttention: Dynamic Memory Management for Serving LLMs without PagedAttention', 'https://arxiv.org/abs/2405.04437', 'Prabhu et al.', 2024, 'The counterargument: use CUDA virtual memory APIs and keep the KV cache virtually contiguous, so unmodified attention kernels still work.', G_KV, ['kv-cache'], false);
R('r-streamingllm', 'paper', 'Efficient Streaming Language Models with Attention Sinks', 'https://arxiv.org/abs/2309.17453', 'Xiao et al., ICLR', 2024, 'The attention sink discovery. Keep the first few tokens and a sliding window and perplexity does not explode. Explains a lot of otherwise mysterious eviction failures.', G_KV, ['kv-cache', 'long-context'], true);
R('r-h2o', 'paper', 'H2O: Heavy-Hitter Oracle for Efficient Generative Inference', 'https://arxiv.org/abs/2306.14048', 'Zhang et al., NeurIPS', 2023, 'Attention-score-based eviction. The baseline every later KV compression paper compares against.', G_KV, ['kv-cache'], false);
R('r-snapkv', 'paper', 'SnapKV: LLM Knows What You are Looking for Before Generation', 'https://arxiv.org/abs/2404.14469', 'Li et al., NeurIPS', 2024, 'Compress the prompt KV at the end of prefill using an observation window. Cheap, and it does not touch the decode loop.', G_KV, ['kv-cache'], false);
R('r-pyramidkv', 'paper', 'PyramidKV: Dynamic KV Cache Compression based on Pyramidal Information Funneling', 'https://arxiv.org/abs/2406.02069', 'Cai et al.', 2024, 'Different layers need different budgets. A useful corrective to uniform-budget eviction schemes.', G_KV, ['kv-cache'], false);
R('r-quest', 'paper', 'Quest: Query-Aware Sparsity for Efficient Long-Context LLM Inference', 'https://arxiv.org/abs/2406.10774', 'Tang et al., ICML', 2024, 'Do not evict, select. Page-level metadata lets you skip most of the KV cache per query while keeping it available.', G_KV, ['kv-cache', 'long-context'], true);
R('r-minference', 'paper', 'MInference 1.0: Accelerating Pre-filling for Long-Context LLMs via Dynamic Sparse Attention', 'https://arxiv.org/abs/2407.02490', 'Jiang et al., NeurIPS', 2024, 'Prefill, not decode, is the long-context bottleneck. Three sparse patterns, chosen per head offline, give up to 10x on a 1M-token prompt.', G_KV, ['long-context', 'prefill'], false);
R('r-duoattention', 'paper', 'DuoAttention: Efficient Long-Context LLM Inference with Retrieval and Streaming Heads', 'https://arxiv.org/abs/2410.10819', 'Xiao et al., ICLR', 2025, 'Splits heads into those that need the full cache and those that do not. A clean, deployable form of head-level KV budgeting.', G_KV, ['kv-cache', 'long-context'], false);
R('r-kivi', 'paper', 'KIVI: A Tuning-Free Asymmetric 2bit Quantization for KV Cache', 'https://arxiv.org/abs/2402.02750', 'Liu et al., ICML', 2024, 'Key cache per-channel, value cache per-token. The asymmetry is the whole insight and it follows from where the outliers live.', G_KV, ['kv-cache', 'quantization'], true);
R('r-kvquant', 'paper', 'KVQuant: Towards 10 Million Context Length LLM Inference with KV Cache Quantization', 'https://arxiv.org/abs/2401.18079', 'Hooper et al., NeurIPS', 2024, 'Pre-RoPE key quantisation plus non-uniform datatypes. Read alongside KIVI to see two different answers to the same outlier problem.', G_KV, ['kv-cache', 'quantization'], false);
R('r-flexgen', 'paper', 'FlexGen: High-Throughput Generative Inference of LLMs with a Single GPU', 'https://arxiv.org/abs/2303.06865', 'Sheng et al., ICML', 2023, 'Offloading done properly: a linear-programming search over the weight/KV/activation placement space. The right mental model for tiered memory.', G_KV, ['offload', 'throughput'], false);
R('r-lmcache', 'code', 'LMCache', 'https://github.com/LMCache/LMCache', 'LMCache Lab', 2025, 'A production KV cache layer across GPU, CPU and disk with cross-instance sharing. The reference implementation for cache offloading.', G_KV, ['kv-cache', 'offload'], true);
R('r-cacheblend', 'paper', 'CacheBlend: Fast Large Language Model Serving for RAG with Cached Knowledge Fusion', 'https://arxiv.org/abs/2405.16444', 'Yao et al., EuroSys', 2025, 'Reuse KV for non-prefix chunks by selectively recomputing the tokens whose attention actually changed. The key unlock for RAG caching.', G_KV, ['kv-cache', 'rag'], false);
R('r-preble', 'paper', 'Preble: Efficient Distributed Prompt Scheduling for LLM Serving', 'https://arxiv.org/abs/2407.00023', 'Srivatsa et al.', 2024, 'Prefix-aware scheduling across replicas. Shows that routing and caching cannot be designed independently.', G_KV, ['routing', 'kv-cache'], false);
R('r-mooncake', 'paper', 'Mooncake: A KVCache-centric Disaggregated Architecture for LLM Serving', 'https://arxiv.org/abs/2407.00079', 'Qin et al., FAST', 2025, 'Kimi in production: a disaggregated KV store as the centre of the architecture, with early rejection under overload. Unusually candid about SLO violation.', G_KV, ['disaggregation', 'kv-cache'], true);

/* ---- Scheduling and batching ---- */
R('r-orca', 'paper', 'Orca: A Distributed Serving System for Transformer-Based Generative Models', 'https://www.usenix.org/conference/osdi22/presentation/yu', 'Yu et al., OSDI', 2022, 'Iteration-level scheduling and selective batching. Continuous batching starts here; everything since is refinement.', G_SCHED, ['batching', 'scheduling'], true);
R('r-anyscale-batching', 'blog', 'How Continuous Batching Enables 23x Throughput in LLM Inference', 'https://www.anyscale.com/blog/continuous-batching-llm-inference', 'Anyscale', 2023, 'The clearest visual explanation of static versus dynamic versus continuous batching, with measurements.', G_SCHED, ['batching'], true);
R('r-modular-batching', 'book', 'Static, Dynamic, and Continuous Batching', 'https://handbook.modular.com/inference-optimization/static-dynamic-continuous-batching/', 'Modular', 2025, 'A crisp taxonomy with the failure mode of each. Read before touching a scheduler config.', G_SCHED, ['batching'], false);
R('r-sarathi', 'paper', 'Taming Throughput-Latency Tradeoff in LLM Inference with Sarathi-Serve', 'https://arxiv.org/abs/2403.02310', 'Agrawal et al., OSDI', 2024, 'Chunked prefill and stall-free batching. The paper that names and fixes generation stalls caused by long prefills.', G_SCHED, ['batching', 'prefill'], true);
R('r-deepspeed-fastgen', 'paper', 'DeepSpeed-FastGen: High-throughput Text Generation via MII and DeepSpeed-Inference', 'https://arxiv.org/abs/2401.08671', 'Holmes et al.', 2024, 'Dynamic SplitFuse: the same idea as chunked prefill arrived at independently. Good for comparing token-budget policies.', G_SCHED, ['batching'], false);
R('r-fastserve', 'paper', 'Fast Distributed Inference Serving for Large Language Models', 'https://arxiv.org/abs/2305.05920', 'Wu et al.', 2023, 'Preemptive multi-level feedback queue scheduling to attack head-of-line blocking without knowing output length in advance.', G_SCHED, ['scheduling'], false);
R('r-llumnix', 'paper', 'Llumnix: Dynamic Scheduling for Large Language Model Serving', 'https://arxiv.org/abs/2406.03243', 'Sun et al., OSDI', 2024, 'Live migration of running requests between instances. Treats scheduling as a cluster problem rather than a per-replica one.', G_SCHED, ['scheduling', 'routing'], false);
R('r-nanoflow', 'paper', 'NanoFlow: Towards Optimal Large Language Model Serving Throughput', 'https://arxiv.org/abs/2408.12757', 'Zhu et al., OSDI', 2025, 'Intra-device parallelism: overlap compute, memory and network-bound operations from different nano-batches on one GPU.', G_SCHED, ['throughput'], false);
R('r-loongserve', 'paper', 'LoongServe: Efficiently Serving Long-Context LLMs with Elastic Sequence Parallelism', 'https://arxiv.org/abs/2404.09526', 'Wu et al., SOSP', 2024, 'Vary the parallelism degree per request phase. The strongest answer so far to mixed short/long-context traffic.', G_SCHED, ['long-context', 'parallelism'], false);
R('r-vtc-fairness', 'paper', 'Fairness in Serving Large Language Models', 'https://arxiv.org/abs/2401.00588', 'Sheng et al., OSDI', 2024, 'Virtual Token Counter. Defines what fairness even means when requests have wildly different token costs.', G_SCHED, ['multi-tenancy', 'fairness'], true);
R('r-vllm-v1-blog', 'blog', 'vLLM V1: A Major Upgrade to vLLM Core Architecture', 'https://vllm.ai/blog/2025-01-27-v1-alpha-release', 'vLLM', 2025, 'Why they rewrote the engine: CPU overhead had become the bottleneck. Isolated EngineCore process, zero-overhead prefix caching, piecewise CUDA graphs.', G_SCHED, ['engine', 'overhead'], true);
R('r-vllm-blog', 'blog', 'vLLM Blog', 'https://vllm.ai/blog', 'vLLM', 2025, 'The running changelog of the field. Skim every release post; the performance notes are where the real numbers live.', G_SCHED, ['engine'], false);
R('r-sglang-paper', 'paper', 'SGLang: Efficient Execution of Structured Language Model Programs', 'https://arxiv.org/abs/2312.07104', 'Zheng et al., NeurIPS', 2024, 'RadixAttention plus a compressed FSM for constrained decoding. The prefix tree is the contribution to steal.', G_SCHED, ['prefix-cache', 'structured'], true);
R('r-sglang-blog', 'blog', 'Fast and Expressive LLM Inference with RadixAttention and SGLang', 'https://lmsys.org/blog/2024-01-17-sglang/', 'LMSYS', 2024, 'The announcement post, with the LRU-on-radix-tree eviction policy explained better than in the paper.', G_SCHED, ['prefix-cache'], false);
R('r-sglang-v04', 'blog', 'SGLang v0.4: Zero-Overhead Batch Scheduler, Cache-Aware Load Balancer', 'https://lmsys.org/blog/2024-12-04-sglang-v0-4/', 'LMSYS', 2024, 'Overlapping the CPU scheduler with GPU execution, and a cache-aware router. Two ideas that show up everywhere afterwards.', G_SCHED, ['scheduling', 'routing'], false);
R('r-nucleus-sampling', 'paper', 'The Curious Case of Neural Text Degeneration', 'https://arxiv.org/abs/1904.09751', 'Holtzman et al., ICLR', 2020, 'Top-p sampling. Read it to understand why the sampler is a quality knob and not just a postprocessing step.', G_SCHED, ['sampling'], false);
R('r-outlines', 'paper', 'Efficient Guided Generation for Large Language Models', 'https://arxiv.org/abs/2307.09702', 'Willard, Louf', 2023, 'Regex and grammar constrained decoding as FSM index construction. Amortises the mask computation to near zero per token.', G_SCHED, ['structured'], false);
R('r-xgrammar', 'paper', 'XGrammar: Flexible and Efficient Structured Generation Engine', 'https://arxiv.org/abs/2411.15100', 'Dong et al.', 2024, 'Context-independent and context-dependent token splitting plus a persistent pushdown stack. The current state of the art for JSON-schema decoding.', G_SCHED, ['structured'], true);

/* ---- Quantization and numerics ---- */
R('r-llm-int8', 'paper', 'LLM.int8(): 8-bit Matrix Multiplication for Transformers at Scale', 'https://arxiv.org/abs/2208.07339', 'Dettmers et al., NeurIPS', 2022, 'The emergent outlier feature discovery. Mixed-precision decomposition is the first honest engineering response to it.', G_QUANT, ['quantization', 'outliers'], true);
R('r-gptq', 'paper', 'GPTQ: Accurate Post-Training Quantization for Generative Pre-trained Transformers', 'https://arxiv.org/abs/2210.17323', 'Frantar et al., ICLR', 2023, 'Second-order weight rounding via a Hessian approximation. Understand the error-compensation update, not just the API.', G_QUANT, ['quantization'], true);
R('r-awq', 'paper', 'AWQ: Activation-aware Weight Quantization for LLM Compression and Acceleration', 'https://arxiv.org/abs/2306.00978', 'Lin et al., MLSys', 2024, 'Protect the 1% of weight channels that matter, identified by activation magnitude. Simpler than GPTQ and usually as good.', G_QUANT, ['quantization'], true);
R('r-awq-repo', 'code', 'llm-awq', 'https://github.com/mit-han-lab/llm-awq', 'MIT HAN Lab', 2024, 'Reference implementation with the fused dequant-GEMM kernels. Read the kernel to see where the speedup actually comes from.', G_QUANT, ['quantization', 'kernels'], false);
R('r-smoothquant', 'paper', 'SmoothQuant: Accurate and Efficient Post-Training Quantization for LLMs', 'https://arxiv.org/abs/2211.10438', 'Xiao et al., ICML', 2022, 'Migrate activation outliers into the weights with a per-channel scale. The mathematically obvious move that nobody had made.', G_QUANT, ['quantization', 'activations'], true);
R('r-quarot', 'paper', 'QuaRot: Outlier-Free 4-Bit Inference in Rotated LLMs', 'https://arxiv.org/abs/2404.00456', 'Ashkboos et al., NeurIPS', 2024, 'Hadamard rotations make outliers disappear because they are computationally invariant. The most elegant result in the quantisation literature.', G_QUANT, ['quantization', 'outliers'], true);
R('r-qserve', 'paper', 'QServe: W4A8KV4 Quantization and System Co-design for Efficient LLM Serving', 'https://arxiv.org/abs/2405.04532', 'Lin et al.', 2024, 'Shows that the dequantisation overhead, not the arithmetic, is what kills naive W4A4. System and algorithm designed together.', G_QUANT, ['quantization', 'kernels'], false);
R('r-zeroquant', 'paper', 'ZeroQuant: Efficient and Affordable Post-Training Quantization for Large-Scale Transformers', 'https://arxiv.org/abs/2206.01861', 'Yao et al., NeurIPS', 2022, 'Group-wise weight and token-wise activation quantisation. The granularity vocabulary comes from here.', G_QUANT, ['quantization'], false);
R('r-qlora', 'paper', 'QLoRA: Efficient Finetuning of Quantized LLMs', 'https://arxiv.org/abs/2305.14314', 'Dettmers et al., NeurIPS', 2023, 'NF4 and double quantisation. Even if you never finetune, the information-theoretic argument for NF4 is worth the read.', G_QUANT, ['quantization'], false);
R('r-kbit-scaling-laws', 'paper', 'The Case for 4-bit Precision: k-bit Inference Scaling Laws', 'https://arxiv.org/abs/2212.09720', 'Dettmers, Zettlemoyer, ICML', 2023, 'For a fixed memory budget, 4-bit is close to optimal. The result that justified the entire 4-bit ecosystem.', G_QUANT, ['quantization'], true);
R('r-fp8-formats', 'paper', 'FP8 Formats for Deep Learning', 'https://arxiv.org/abs/2209.05433', 'Micikevicius et al.', 2022, 'E4M3 versus E5M2, and why you need both. The spec behind every Hopper FP8 deployment.', G_QUANT, ['fp8', 'numerics'], true);
R('r-mxfp4-spec', 'paper', 'Microscaling Data Formats for Deep Learning', 'https://arxiv.org/abs/2310.10537', 'Rouhani et al.', 2023, 'MX formats: a shared exponent per small block. This is what Blackwell FP4 implements in hardware.', G_QUANT, ['fp4', 'numerics'], false);
R('r-marlin', 'code', 'Marlin', 'https://github.com/IST-DASLab/marlin', 'IST-DASLab', 2024, 'A W4A16 GEMM kernel that actually hits near-4x at realistic batch sizes. Read it to understand why most quantised kernels do not.', G_QUANT, ['kernels', 'quantization'], false);
R('r-llm-compressor', 'code', 'LLM Compressor', 'https://github.com/vllm-project/llm-compressor', 'vLLM Project', 2025, 'The production path from a BF16 checkpoint to a vLLM-loadable quantised one. GPTQ, AWQ, SmoothQuant and FP8 in one library.', G_QUANT, ['quantization', 'tooling'], true);

/* ---- Speculative and parallel decoding ---- */
R('r-spec-decode', 'paper', 'Fast Inference from Transformers via Speculative Decoding', 'https://arxiv.org/abs/2211.17192', 'Leviathan et al., ICML', 2023, 'The original. The modified rejection sampling proof in section 2 is what guarantees the output distribution is unchanged; do not skip it.', G_SPEC, ['speculative'], true);
R('r-spec-sampling', 'paper', 'Accelerating Large Language Model Decoding with Speculative Sampling', 'https://arxiv.org/abs/2302.01318', 'Chen et al., DeepMind', 2023, 'Concurrent independent derivation, applied to Chinchilla 70B. Read both; the notation differs and the intersection is the real idea.', G_SPEC, ['speculative'], false);
R('r-medusa', 'paper', 'Medusa: Simple LLM Inference Acceleration Framework with Multiple Decoding Heads', 'https://arxiv.org/abs/2401.10774', 'Cai et al.', 2024, 'No draft model: extra heads on the target predict several positions, verified with a tree attention mask.', G_SPEC, ['speculative'], true);
R('r-eagle', 'paper', 'EAGLE: Speculative Sampling Requires Rethinking Feature Uncertainty', 'https://arxiv.org/abs/2401.15077', 'Li et al., ICML', 2024, 'Autoregress in feature space rather than token space, with one-step-ahead token conditioning. The highest acceptance rates in the literature.', G_SPEC, ['speculative'], true);
R('r-eagle2', 'paper', 'EAGLE-2: Faster Inference of Language Models with Dynamic Draft Trees', 'https://arxiv.org/abs/2406.16858', 'Li et al., EMNLP', 2024, 'Context-dependent draft tree shape, using the draft model confidence as a proxy for acceptance probability.', G_SPEC, ['speculative'], false);
R('r-specinfer', 'paper', 'SpecInfer: Accelerating LLM Serving with Tree-based Speculative Inference', 'https://arxiv.org/abs/2305.09781', 'Miao et al., ASPLOS', 2024, 'Token-tree verification with multiple small draft models. The tree-attention mask construction is the reusable piece.', G_SPEC, ['speculative'], false);
R('r-lookahead', 'paper', 'Break the Sequential Dependency of LLM Inference Using Lookahead Decoding', 'https://arxiv.org/abs/2402.02057', 'Fu et al., ICML', 2024, 'Jacobi iteration plus an n-gram pool: parallel decoding with no draft model at all.', G_SPEC, ['speculative'], false);
R('r-deepseek-v3', 'paper', 'DeepSeek-V3 Technical Report', 'https://arxiv.org/abs/2412.19437', 'DeepSeek-AI', 2024, 'Multi-token prediction, MLA, FP8 training, and an auxiliary-loss-free load balance for 671B/37B MoE. The most information-dense systems report of 2024.', G_SPEC, ['moe', 'speculative', 'fp8'], true);
R('r-vllm-spec-blog', 'blog', 'How Speculative Decoding Boosts vLLM Performance by up to 2.8x', 'https://vllm.ai/blog/2024-10-17-spec-decode', 'vLLM', 2024, 'The engineering reality: speculation helps at low batch size and hurts at high batch size, because it trades spare FLOPs for latency.', G_SPEC, ['speculative'], true);
R('r-vllm-spec-docs', 'docs', 'vLLM: Speculative Decoding', 'https://docs.vllm.ai/en/stable/features/spec_decode.html', 'vLLM', 2025, 'Configuration surface for ngram, draft-model and EAGLE methods, with the caveats stated plainly.', G_SPEC, ['speculative'], false);
R('r-speculators', 'code', 'Speculators', 'https://github.com/vllm-project/speculators', 'vLLM Project', 2025, 'A unified format and training toolkit for speculative decoding algorithms. Where draft-model work is converging.', G_SPEC, ['speculative', 'tooling'], false);
R('r-modular-spec', 'book', 'Speculative Decoding', 'https://handbook.modular.com/inference-optimization/speculative-decoding/', 'Modular', 2025, 'The cleanest short derivation of expected speedup as a function of acceptance rate and draft cost.', G_SPEC, ['speculative'], true);

/* ---- Distributed and disaggregated serving ---- */
R('r-megatron', 'paper', 'Megatron-LM: Training Multi-Billion Parameter Language Models Using Model Parallelism', 'https://arxiv.org/abs/1909.08053', 'Shoeybi et al.', 2019, 'The column-then-row tensor parallel decomposition that puts exactly one all-reduce per block. Still the layout every engine uses.', G_DIST, ['parallelism'], true);
R('r-distserve', 'paper', 'DistServe: Disaggregating Prefill and Decoding for Goodput-optimized LLM Serving', 'https://arxiv.org/abs/2401.09670', 'Zhong et al., OSDI', 2024, 'Prefill and decode have opposite optimal parallelism. Separating them raises goodput by up to 7.4x. Note the goodput definition; it is the honest metric.', G_DIST, ['disaggregation'], true);
R('r-splitwise', 'paper', 'Splitwise: Efficient Generative LLM Inference Using Phase Splitting', 'https://arxiv.org/abs/2311.18677', 'Patel et al., ISCA', 2024, 'The same idea from a datacentre-power perspective: put decode on cheaper, lower-power hardware. Includes real Azure production traces.', G_DIST, ['disaggregation', 'economics'], true);
R('r-modular-disagg', 'book', 'Prefill-Decode Disaggregation', 'https://handbook.modular.com/inference-optimization/prefill-decode-disaggregation/', 'Modular', 2025, 'Practical: when the KV transfer cost outweighs the scheduling benefit, and how to tell.', G_DIST, ['disaggregation'], false);
R('r-megablocks', 'paper', 'MegaBlocks: Efficient Sparse Training with Mixture-of-Experts', 'https://arxiv.org/abs/2211.15841', 'Gale et al., MLSys', 2023, 'Block-sparse MoE without token dropping. The grouped-GEMM formulation is what every MoE inference kernel now uses.', G_DIST, ['moe', 'kernels'], false);
R('r-fastmoe', 'paper', 'FastMoE: A Fast Mixture-of-Expert Training System', 'https://arxiv.org/abs/2103.13262', 'He et al.', 2021, 'The all-to-all dispatch/combine pattern, spelled out. Read it for the communication analysis rather than the training details.', G_DIST, ['moe'], false);
R('r-deepseek-v2', 'paper', 'DeepSeek-V2: A Strong, Economical, and Efficient Mixture-of-Experts Language Model', 'https://arxiv.org/abs/2405.04434', 'DeepSeek-AI', 2024, 'Multi-head latent attention: compress KV into a low-rank latent and cache that instead. A 93% KV reduction with no quality loss.', G_DIST, ['moe', 'kv-cache'], true);
R('r-deepep', 'code', 'DeepEP', 'https://github.com/deepseek-ai/DeepEP', 'DeepSeek', 2025, 'Expert-parallel all-to-all communication kernels, including a low-latency path for decode. Rare production-grade MoE comms code.', G_DIST, ['moe', 'kernels'], false);
R('r-moe-hf', 'blog', 'Mixture of Experts Explained', 'https://huggingface.co/blog/moe', 'Hugging Face', 2023, 'The gentle introduction. Read before the MoE papers if routing and capacity factor are new to you.', G_DIST, ['moe'], false);
R('r-modular-parallelism', 'book', 'Data, Tensor, Pipeline, Expert and Hybrid Parallelism', 'https://handbook.modular.com/inference-optimization/data-tensor-pipeline-expert-hybrid-parallelism/', 'Modular', 2025, 'One page that finally makes the five parallelism axes and their interaction legible.', G_DIST, ['parallelism'], true);
R('r-nccl-docs', 'docs', 'NVIDIA Collective Communications Library (NCCL)', 'https://docs.nvidia.com/deeplearning/nccl/user-guide/docs/index.html', 'NVIDIA', 2025, 'Where all-reduce cost really comes from. The environment variable reference is what you will actually need at 3am.', G_DIST, ['networking'], false);
R('r-nixl', 'code', 'NIXL', 'https://github.com/ai-dynamo/nixl', 'NVIDIA Dynamo', 2025, 'The transfer library that makes KV cache movement between disaggregated workers fast enough to be worth doing.', G_DIST, ['disaggregation', 'networking'], false);
R('r-dynamo', 'docs', 'NVIDIA Dynamo', 'https://docs.nvidia.com/dynamo/latest/', 'NVIDIA', 2025, 'A datacentre-scale inference framework built around disaggregation, a KV-aware router and dynamic GPU planning.', G_DIST, ['disaggregation', 'serving'], false);
R('r-llm-d', 'code', 'llm-d', 'https://github.com/llm-d/llm-d', 'llm-d', 2025, 'Kubernetes-native distributed inference: vLLM plus inference-aware routing plus disaggregation. Read the well-lit-path docs.', G_DIST, ['kubernetes', 'serving'], false);

